#!/usr/bin/env node
"use strict";
const fs=require("node:fs"),path=require("node:path"),crypto=require("node:crypto");
const ROOT=path.resolve(process.cwd());
const SPEC=JSON.parse(fs.readFileSync(path.join(ROOT,"doc/local-game-tree-geometry-transfer-compatibility-instrument/prereg/STAGE_1R_RETEST_SPEC.json"),"utf8"));
function need(x,m){if(!x)throw new Error(m);}function parse(){const a=process.argv.slice(2),o={};for(let i=0;i<a.length;i++)if(a[i].startsWith("--"))o[a[i].slice(2)]=a[i+1]&&!a[i+1].startsWith("--")?a[++i]:true;return o;}function sha(b){return crypto.createHash("sha256").update(b).digest("hex");}
function expected(){const m=new Map();for(const block of ["SFCDF","SILGM","GCLD"]){const r=SPEC.freshSeedSlots.primary[block];for(let s=r.seedStart;s<=r.seedEnd;s++)m.set(s,block);}return m;}
function walk(dir){const out=[];for(const ent of fs.readdirSync(dir,{withFileTypes:true})){const p=path.join(dir,ent.name);if(ent.isDirectory())out.push(...walk(p));else if(ent.isFile()&&ent.name==="source.json")out.push(p);}return out;}
function stableManifestCore(rows){return {stageId:SPEC.stageId,sourceArtifactCount:rows.length,primaryCount:rows.filter(x=>x.seedRole==="PRIMARY").length,reserveCount:rows.filter(x=>x.seedRole==="PAIRED-RESERVE").length,entries:rows.map(({block,slotSeed,effectiveSeed,seedRole,sha256})=>({block,slotSeed,effectiveSeed,seedRole,sha256}))};}
function main(){const a=parse(),input=path.resolve(a.input||""),output=path.resolve(a.output||"");need(input&&output&&fs.existsSync(input),"input/output required");const exp=expected(),files=walk(input);need(files.length===SPEC.freshSeedSlots.primaryCount,`expected ${SPEC.freshSeedSlots.primaryCount} source files, got ${files.length}`);const seen=new Set(),rows=[];for(const f of files){const buf=fs.readFileSync(f),j=JSON.parse(buf.toString("utf8"));need(j.stageId===SPEC.stageId,"stage identity mismatch");need(exp.get(j.slotSeed)===j.block,`slot/block mismatch ${j.slotSeed}`);need(!seen.has(j.slotSeed),`duplicate slot ${j.slotSeed}`);seen.add(j.slotSeed);if(j.seedRole==="PRIMARY")need(j.effectiveSeed===j.slotSeed,`bad primary effective seed ${j.slotSeed}`);else if(j.seedRole==="PAIRED-RESERVE")need(j.effectiveSeed===j.slotSeed+1000000,`bad reserve effective seed ${j.slotSeed}`);else throw new Error(`bad seed role ${j.slotSeed}`);need(j.effectiveSeed<40100000||j.effectiveSeed>40199999,"quarantined 401 namespace reuse detected");const dest=path.join(output,"source",j.block,`${j.slotSeed}.json`);fs.mkdirSync(path.dirname(dest),{recursive:true});fs.writeFileSync(dest,buf);rows.push({block:j.block,slotSeed:j.slotSeed,effectiveSeed:j.effectiveSeed,seedRole:j.seedRole,sha256:sha(buf)});}need(seen.size===exp.size,"coverage mismatch");rows.sort((a,b)=>a.slotSeed-b.slotSeed);const reserveCount=rows.filter(x=>x.seedRole==="PAIRED-RESERVE").length;need(reserveCount<=SPEC.freshSeedSlots.maxInfrastructureReplacementsTotal,"reserve count exceeds frozen maximum");const core=stableManifestCore(rows);const manifest={schemaVersion:1,...core,deterministicCoreSha256:sha(Buffer.from(JSON.stringify(core),"utf8"))};fs.mkdirSync(output,{recursive:true});fs.writeFileSync(path.join(output,"SOURCE_MANIFEST.json"),JSON.stringify(manifest,null,2)+"\n");process.stdout.write(JSON.stringify({event:"SOURCE-BUNDLE-COMMIT",sourceCount:rows.length,reserveCount,deterministicCoreSha256:manifest.deterministicCoreSha256})+"\n");}
main();
